func withRetry<T>(_ attempts: Int, _ op: () async throws -> T) async throws -> T {
    var last: Error?
    for attempt in 1...attempts {
        do { return try await op() }
        catch is CancellationError { throw CancellationError() }   // never retry
        catch let e where isTransient(e) {
            last = e
            if attempt < attempts { try await Task.sleep(for: .milliseconds(200 * attempt)) }
        }
        catch { throw error }                                     // permanent: fail fast
    }
    throw last!
}

